create extension if not exists pgcrypto;
create type reservation_status as enum ('pending','approved','rejected','expired');
create type ticket_status as enum ('valid','used','cancelled');
create table films(id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,genre text,duration text,rating text,schedule timestamptz,capacity int not null check(capacity=200),ticket_price numeric(10,2) not null default 3,poster_path text,active boolean default true,created_at timestamptz default now());
create table products(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,price numeric(10,2) not null,stock int not null default 0,active boolean default true,image_path text,components jsonb default '{}'::jsonb,created_at timestamptz default now());
create table reservations(id uuid primary key default gen_random_uuid(),code text unique not null,buyer_name text not null,buyer_phone text not null,buyer_email text not null,student_code text,film_id uuid not null references films(id),ticket_quantity int not null check(ticket_quantity between 1 and 6),total_amount numeric(10,2) not null,status reservation_status not null default 'pending',proof_path text not null,yape_reference text unique,expires_at timestamptz not null default(now()+interval '2 hours'),approved_at timestamptz,rejected_reason text,created_at timestamptz default now(),updated_at timestamptz default now());
create table reservation_items(id uuid primary key default gen_random_uuid(),reservation_id uuid references reservations(id) on delete restrict,product_id uuid references products(id),quantity int not null check(quantity>0),unit_price numeric(10,2) not null,created_at timestamptz default now());
create table tickets(id uuid primary key default gen_random_uuid(),reservation_id uuid references reservations(id) on delete restrict,film_id uuid references films(id),ticket_number int not null check(ticket_number between 1 and 200),qr_token uuid unique not null default gen_random_uuid(),download_token uuid unique not null default gen_random_uuid(),status ticket_status not null default 'valid',used_at timestamptz,created_at timestamptz default now(),unique(film_id,ticket_number));
create table audit_log(id bigint generated always as identity primary key,actor_id uuid,action text not null,entity_type text not null,entity_id uuid,payload jsonb default '{}'::jsonb,created_at timestamptz default now());
create table app_settings(key text primary key,value jsonb not null,updated_at timestamptz default now());
insert into films(slug,title,genre,capacity,ticket_price) values('demon-slayer','Demon Slayer: Kimetsu no Yaiba – Castillo Infinito','Animación · Acción · Fantasía',200,3),('el-rito','El rito','Terror · Suspenso',200,3);
insert into products(slug,name,price,stock,components) values('popcorn','Popcorn',3,200,'{}'),('gaseosa','Gaseosa personal',3,200,'{}'),('combo','Combo Cine',5,200,'{"popcorn":1,"gaseosa":1}');
insert into app_settings(key,value) values('event','{"date":"2026-10-21","venue":"Auditorio R","yape":"987712599","pending_minutes":120}');
alter table films enable row level security;alter table products enable row level security;alter table reservations enable row level security;alter table reservation_items enable row level security;alter table tickets enable row level security;alter table audit_log enable row level security;alter table app_settings enable row level security;
create policy public_films on films for select using(active);create policy public_products on products for select using(active);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('payment-proofs','payment-proofs',false,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=false,file_size_limit=5242880,allowed_mime_types=array['image/jpeg','image/png','image/webp'];
create sequence reservation_code_seq start 1;
create or replace function create_reservation_atomic(p_film_slug text,p_ticket_qty int,p_buyer_name text,p_phone text,p_email text,p_student_code text,p_popcorn int,p_soda int,p_combo int,p_total numeric,p_proof_path text,p_inventory_use jsonb) returns text language plpgsql security definer set search_path=public as $$declare v_film films;v_code text;v_reserved int;v_res uuid;v_product products;v_expected numeric;begin if p_ticket_qty<1 or p_ticket_qty>6 then raise exception 'Cantidad inválida';end if;select * into v_film from films where slug=p_film_slug and active for update;if not found then raise exception 'Película no disponible';end if;select coalesce(sum(ticket_quantity),0) into v_reserved from reservations where film_id=v_film.id and(status='approved' or(status='pending' and expires_at>now()));if v_reserved+p_ticket_qty>v_film.capacity then raise exception 'No hay suficientes entradas';end if;v_expected=p_ticket_qty*v_film.ticket_price+p_popcorn*3+p_soda*3+p_combo*5;if v_expected<>p_total then raise exception 'Total inválido';end if;for v_product in select * from products where slug in('popcorn','gaseosa') for update loop if v_product.stock<(p_inventory_use->>v_product.slug)::int then raise exception 'Stock insuficiente: %',v_product.name;end if;end loop;v_code='CE-2026-'||lpad(nextval('reservation_code_seq')::text,4,'0');insert into reservations(code,buyer_name,buyer_phone,buyer_email,student_code,film_id,ticket_quantity,total_amount,proof_path) values(v_code,p_buyer_name,p_phone,lower(p_email),nullif(p_student_code,''),v_film.id,p_ticket_qty,p_total,p_proof_path) returning id into v_res;insert into reservation_items(reservation_id,product_id,quantity,unit_price) select v_res,id,q,price from(select id,price,case slug when'popcorn'then p_popcorn when'gaseosa'then p_soda when'combo'then p_combo end q from products where slug in('popcorn','gaseosa','combo'))s where q>0;return v_code;end$$;
create or replace function approve_reservation_atomic(p_reservation_id uuid,p_yape_reference text,p_actor uuid) returns void language plpgsql security definer set search_path=public as $$declare r reservations;start_no int;i int;begin select * into r from reservations where id=p_reservation_id for update;if r.status<>'pending' then raise exception 'La reserva ya fue procesada';end if;if p_yape_reference is null or length(trim(p_yape_reference))<3 then raise exception 'Referencia de Yape requerida';end if;select coalesce(max(ticket_number),0)+1 into start_no from tickets where film_id=r.film_id for update;if start_no+r.ticket_quantity-1>200 then raise exception 'Aforo agotado';end if;update reservations set status='approved',approved_at=now(),yape_reference=p_yape_reference,updated_at=now() where id=r.id;for i in 0..r.ticket_quantity-1 loop insert into tickets(reservation_id,film_id,ticket_number)values(r.id,r.film_id,start_no+i);end loop;insert into audit_log(actor_id,action,entity_type,entity_id)values(p_actor,'approve','reservation',r.id);end$$;
create or replace function check_in_ticket_atomic(p_token uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare t tickets;f films;begin select * into t from tickets where qr_token=p_token for update;if not found then return jsonb_build_object('ok',false,'message','Entrada inválida');end if;if t.status='used' then return jsonb_build_object('ok',false,'message','Entrada ya utilizada','used_at',t.used_at);end if;if t.status<>'valid' then return jsonb_build_object('ok',false,'message','Entrada no válida');end if;update tickets set status='used',used_at=now() where id=t.id;select * into f from films where id=t.film_id;return jsonb_build_object('ok',true,'message','Ingreso autorizado','ticket_number',lpad(t.ticket_number::text,3,'0'),'movie',f.title);end$$;
revoke all on function create_reservation_atomic from public;revoke all on function approve_reservation_atomic from public;revoke all on function check_in_ticket_atomic from public;grant execute on function create_reservation_atomic to service_role;grant execute on function approve_reservation_atomic to service_role;grant execute on function check_in_ticket_atomic to service_role;
